return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'Přesune knihovnu médií tohoto webu do objektového úložiště Zinn® a bude ji poskytovat z CDN. Konfiguruje se z vašeho řídicího panelu Zinn® – do WordPress se nezadává žádný přístupový klíč.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Uloženo. Zadáním nové hodnoty ji nahradíte.','Filter this list…'=>'Filtrovat tento seznam…','Filter this list'=>'Filtrovat tento seznam','Nothing matches that filter.'=>'T tomuto filtru nic neodpovídá.','Add a row'=>'Přidat řádek','Remove this row'=>'Odstranit tento řádek','Remove'=>'Odstranit','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® – přehled','Overview'=>'Přehled','Every Zinn® plugin on this site, and whether it is working.'=>'Každý Zinn® plugin na tomto webu a zda funguje.','No connection is needed for this plugin.'=>'Pro tento plugin není nutné žádné připojení.','Open settings'=>'Otevřít nastavení','You do not have permission to change these settings.'=>'Nemáte oprávnění tato nastavení měnit.','Settings sections'=>'Sekce nastavení','Support'=>'Podpora','Save changes'=>'Uložit změny','Tools'=>'Nástroje','Export settings'=>'Export nastavení','Reset to defaults'=>'Obnovit výchozí nastavení','This puts every setting on this plugin back to its default. Continue?'=>'Tímto obnovíte všechna nastavení tohoto pluginu na výchozí hodnoty. Pokračovat?','Diagnostics for support'=>'Diagnostika pro podporu','Import a settings file'=>'Importovat soubor nastavení','Import'=>'Importovat','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Exportované soubory nikdy neobsahují hesla, tokeny ani klíče API – na novém webu je budete muset zadat znovu.','Settings saved.'=>'Nastavení byla uložena.','Every setting on this plugin is back to its default.'=>'Všechna nastavení tohoto pluginu byla vrácena na výchozí hodnoty.','Done.'=>'Hotovo.','That action is not available.'=>'Tato akce není k dispozici.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tento soubor se nepodařilo přečíst. Zvolte soubor nastavení exportovaný z pluginu Zinn®.','That file is too large to be a settings export.'=>'Tento soubor je příliš velký na to, aby byl exportem nastavení.','That file is not a Zinn® settings export.'=>'Tento soubor není exportem nastavení Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Tento soubor byl exportován z jiného modulu (%s), takže jeho importem by se uložilo nastavení, kterému tento modul nerozumí.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d nastavení importováno. Hesla a klíče API se neexportují, proto je prosím zadejte znovu.' . "\0" . '%d nastavení bylo importováno. Hesla a klíče API se do exportu nezahrnují, takže je musíte zadat znovu.' . "\0" . '%d nastavení bylo importováno. Hesla a klíče API se do exportu nezahrnují, takže je musíte zadat znovu.' . "\0" . '%d nastavení bylo importováno. Hesla a klíče API se do exportu nezahrnují, takže je musíte zadat znovu.','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® nevrátil token. Na tomto webu nebylo nic změněno.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'Tento web již není připojen k offloadu médií Zinn®. Nová nahrávání zůstanou na tomto serveru. Spárujte jej znovu ze svého řídicího panelu Zinn Digital®.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® odpověděl kódem HTTP %d.','Disconnected by Zinn Digital®.'=>'Odpojeno od Zinn Digital®.','Connected'=>'Připojeno','Connecting…'=>'Připojování…','Connected, but something needs attention'=>'Připojeno, ale některé věci vyžadují pozornost','Not connected'=>'Nepřipojeno','Running on your own account'=>'Běží na vašem vlastním účtu','We could not check this'=>'Nepodařilo se nám to zkontrolovat','This plugin did not say why. Send a diagnostics report and we will look.'=>'Tento plugin neuvedl důvod. Odešlete diagnostickou zprávu a my se na to podíváme.','Connection status'=>'Stav připojení','Last checked %s ago.'=>'Naposledy zkontrolováno před %s.','(opens in a new tab)'=>'(otevře se na nové kartě)','Send this to Zinn® support'=>'Odeslat na podporu Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Přesně toto bude odesláno – nic jiného a nic skrytého. Vaše hesla, tokeny a klíče API v tom nejsou obsaženy.','The diagnostics report that will be sent'=>'Diagnostická zpráva, která bude odeslána','Copy to clipboard'=>'Kopírovat do schránky','Send this report to Zinn® support'=>'Odešlete tento report podpoře Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otevřeme pro vás tiket podpory a odpovíme e-mailem. Pokud jej raději nechcete odesílat, zkopírujte jej výše a vložte si jej do tiketu sami.','Copied'=>'Zkopírováno','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Zinn Digital® se nepodařilo z tohoto serveru (%s) kontaktovat. Zkopírujte výše uvedený záznam a místo toho otevřete tiket – ve vašem nastavení není nic špatně.','Sent. Zinn® support has your report and will reply by email.'=>'Podpora Zinn® obdržela vaše hlášení a odpoví vám e-mailem.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podpora Zinn® obdržela vaše hlášení – referenční číslo %s – a odpoví vám e-mailem.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Odeslali jste několik hlášení v krátké době. Počkejte několik minut a zkuste to znovu – ty dřívější dorazily.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® nyní nemohl přijmout hlášení – chyba je na naší straně, nikoli vaší. Zkuste to brzy znovu, nebo zkopírujte výše uvedené hlášení do tiketu.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Zpráva byla odmítnuta (HTTP %d). Zkopírujte ji výše a otevřete tiket s uvedením tohoto čísla.','%s — guides and services'=>'%s — průvodce a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku %s','Hide this'=>'Skrýt toto','Zinn® hosting for WordPress'=>'Zinn® hosting pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro lidi, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte a prodávejte zaběhnuté weby, domény a umístění odkazů. Peníze jsou bezpečně uloženy, dokud nejsou obě strany spokojené.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tím živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globální tržiště pro lidi na volné noze: procházejte více než 10 000 hotových služeb od tvůrců obsahu, designérů, vývojářů a SEO specialistů, nebo zadejte projekt a nechte je přihazovat.','Media Offload'=>'Přesun médií','Connection'=>'Připojení','What gets moved'=>'Co bude přeneseno','How media is served'=>'Jak se média poskytují','Move a batch now'=>'Přesunout dávku hned','Media already moved is never affected by a change here — its address does not change.'=>'Média, která již byla přesunuta, nejsou touto změnou nikdy ovlivněna – jejich adresa se nemění.','New uploads'=>'Nové nahrávare','Move new uploads to Zinn® storage as they arrive'=>'Přesunout nové soubory do úložiště Zinn® ihned po jejich nahrání','Existing media'=>'Existující média','Keep moving the media library that is already here'=>'Pokračujte v přesunu zde již existující knihovny médií','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'Několik souborů za hodinu na pozadí, s navázáním tam, kde se skončilo. Vypnutím se proces pozastaví; nic, co již bylo přesunuto, se nevrátí zpět.','Files per hourly pass'=>'Souborů za hodinu','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'Každá příloha se skládá z několika souborů a každý z nich představuje úplný upload. Zvýšte tuto hodnotu na rychlém hostingu s velkorysem limitem provádění; snižte ji, pokud jsou běhy předčasně ukončovány.','Leave files smaller than'=>'Nechat soubory menší než','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'Kilobajty. Malá ikona stojí na dodatečném připojení více, než kolik ušetří na disku, takže je málokdy důvod ji přesouvat. Nastavením na hodnotu 0 přesunete vše.','Never move these types'=>'Tyto typy nikdy nepřesouvat','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'Užitečné, když plugin čte soubor přímo z disku — písmo, PDF, do kterého tvůrce formulářů razítkuje, audio soubor, ve kterém přehrávač vyhledává.','These two are the ones to be careful with — read each description before changing it.'=>'Na tyto dva je třeba dávat pozor — před každou změnou si přečtěte příslušný popis.','Serve from Zinn® storage'=>'Podávat z úložiště Zinn®','Point image and file addresses at Zinn® storage'=>'Směrujte adresy obrázků a souborů na úložiště Zinn®','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'Vypnuto, soubory jsou nahrány, ale stále jsou poskytovány z tohoto serveru – což je bezpečný stav, než zkontrolujete, zda dorazilo vše. Zapnuto, návštěvníkům jsou soubory poskytovány z úložiště a tento server přestane přenášet provoz.','Free the disk space'=>'Uvolnit místo na disku','Delete the local copy once every size has uploaded'=>'Smazat místní kopii, jakmile se nahraje každá velikost','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'Toto je bod přesunu a je to také nevratná polovina. Nechte ji vypnutou, dokud nebude zapnuta možnost „Serve from Zinn® storage“ a nezkontrolujete svůj web – místní kopie je to jediné, co vás zachrání, pokud něco uniklo.','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'Smazání místních kopií nelze z této obrazovky vrátit zpět. Nejprve vytvořte zálohu – zásuvný modul Zinn® Connector to zvládne za vás.','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'Tento web ještě není připojen k úložišti Zinn®, takže není kam přesunout média.','%d attachment moved.'=>'%d příloha byla přesunuta.' . "\0" . '%d příloh přesunuto.' . "\0" . '%d příloh přesunuto.' . "\0" . '%d příloh přesunuto.','This site is not connected to Zinn® storage.'=>'Tento web není spojen se úložištěm Zinn®.','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'Nic není v nepořádku – dosud pouze neproběhlo spárování. Média zůstanou na tomto serveru, dokud k němu nedojde.','Connected, but the last upload failed.'=>'Připojeno, ale poslední odeslání se nezdařilo.','Try a batch now'=>'Zkusit dávku nyní','Connected. Every attachment has been moved.'=>'Připojeno. Všechny přílohy byly přesunuty.','Connected. %1$s of %2$s attachments still on this server.'=>'Připojeno. %1$s z %2$s příloh je stále na tomto serveru.','Moved so far'=>'Přesunuto dosud','%1$s files, %2$s'=>'%1$s souborů, %2$s','Still on this server'=>'Stále na tomto serveru','%1$s of %2$s attachments'=>'%1$s z %2$s příloh','Served from'=>'Obsluhováno z','this server'=>'tento server','Connect this site'=>'Připojit tento web','Open your Zinn Digital® dashboard, go to Storage → Media offload, and press “Pair a site”. Paste the code below.'=>'Otevřete svůj řídicí panel Zinn Digital®, přejděte na Úložiště → Přesun médií a stiskněte „Spárovat web“. Vložte níže uvedený kód.','Pairing code'=>'Párovací kód','Disconnect this site'=>'Odpojit tento web','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'Nové soubory zůstanou na tomto serveru. Již přesunutá média fungují dál – jejich adresa se nemění.','You do not have permission to manage this site.'=>'Nemáte oprávnění ke správě tohoto webu.','Paste the pairing code from your Zinn Digital® dashboard.'=>'Vložte párový kód z vašeho řídicího panelu Zinn Digital®.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'Připojeno. Nová nahrání budou odteď uložena u Zinn Digital® a vaše stávající média se na pozadí přesunou.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'Odpojeno. Již přesunutá média fungují dál; nové nahrávky zůstávají na tomto serveru.','That file could not be read from this server, so nothing was uploaded.'=>'Tento soubor nebylo možné z tohoto serveru přečíst, takže nebyl nahrán žádný obsah.','This site could not stream the upload, so nothing was sent.'=>'Tento web nemohl streamovat nahrávaný soubor, takže neběhlo odesláno nic.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'Tento soubor má velikost %1$s a PHP tohoto webu nemá cURL, takže maximální velikost pro nahrání je %2$s.','The upload could not be completed.'=>'Nahrávání se nepodařilo dokončit.','Storage refused the upload (HTTP %d).'=>'Úložisko odmietlo nahrávanie (HTTP %d).','Style preset'=>'Styl předvolby','A starting point. Anything below overrides it.'=>'Výchozí bod. Cokoliv níže má před ním přednost.','Use my own colours and sizes'=>'Použít vlastní barvy a velikosti','Leave this off and the preset is used exactly as it is.'=>'Pokud toto vypnete, předvolba se použije přesně tak, jak je.','See the Zinn Digital® release notes.'=>'Prohlédněte si poznámky k vydání Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.']];